package main

import (
	"fmt"
	"sort"
)

type Product struct {
	Name     string
	Category string
	Price    int
}

type Order struct {
	Item string
	Day  int
}

func main() {
	products := []Product{
		{"pen", "office", 3},
		{"apple", "food", 2},
		{"desk", "office", 120},
		{"bread", "food", 4},
		{"lamp", "office", 25},
		{"milk", "food", 1},
	}
	sort.Slice(products, func(i, j int) bool {
		if products[i].Category != products[j].Category {
			return products[i].Category < products[j].Category
		}
		return products[i].Price < products[j].Price
	})
	for _, p := range products {
		fmt.Printf("%-6s %-5s %d\n", p.Category, p.Name, p.Price)
	}

	orders := []Order{{"tea", 2}, {"cake", 1}, {"soup", 2}, {"jam", 3}, {"bun", 1}}
	sort.SliceStable(orders, func(i, j int) bool {
		return orders[i].Day < orders[j].Day
	})
	for _, o := range orders {
		fmt.Printf("day %d: %s\n", o.Day, o.Item)
	}
}

