import (
	"fmt"
	"sort"
)

func main() {
	ids := []int{3, 8, 15, 23, 42}

	i := sort.SearchInts(ids, 23)
	fmt.Printf("23: index %d, found %t\n", i, i < len(ids) && ids[i] == 23)

	i = sort.SearchInts(ids, 10)
	fmt.Printf("10: index %d, found %t\n", i, i < len(ids) && ids[i] == 10)

	names := []string{"ana", "bo", "cy", "dee"}
	j := sort.SearchStrings(names, "cy")
	fmt.Printf("cy: index %d, found %t\n", j, j < len(names) && names[j] == "cy")

	k := sort.Search(len(ids), func(i int) bool { return ids[i] >= 20 })
	if k < len(ids) {
		fmt.Printf("first id >= 20: %d at index %d\n", ids[k], k)
	}
}

