package main

import (
	"fmt"
	"sort"
)

func main() {
	scores := []int{55, 61, 70, 78, 92}
	fruits := []string{"apple", "fig", "kiwi", "plum"}

	i := sort.SearchInts(scores, 70)
	fmt.Printf("70: index %d, found %t\n", i, i < len(scores) && scores[i] == 70)

	i = sort.SearchInts(scores, 80)
	fmt.Printf("80: index %d, found %t\n", i, i < len(scores) && scores[i] == 80)

	j := sort.SearchStrings(fruits, "grape")
	fmt.Printf("grape: index %d, found %t\n", j, j < len(fruits) && fruits[j] == "grape")

	// the first index with a score of at least 75 equals the count of scores below 75
	below := sort.Search(len(scores), func(i int) bool { return scores[i] >= 75 })
	fmt.Println("below 75:", below)
}

