package main

import (
	"container/heap"
	"fmt"
)

type MaxHeap []int

func (h MaxHeap) Len() int      { return len(h) }
func (h MaxHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h MaxHeap) Less(i, j int) bool {
	return h[i] > h[j]
}

func (h *MaxHeap) Push(x interface{}) {
	*h = append(*h, x.(int))
}

func (h *MaxHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	h := &MaxHeap{}
	var top []int
	for _, p := range []int{3, 9, 4, 7, 1} {
		heap.Push(h, p)
	}
	for i := 0; i < 3; i++ {
		top = append(top, heap.Pop(h).(int))
	}
	fmt.Println("top three:", top)
	fmt.Println("left:", h.Len())
}
